#!/bin/bash
# ======================================================================
#  Install_KPA1500_SDR_Bridge.sh  -  installer for Mac and Linux (experimental)
#  KPA1500 SDR Bridge: Elecraft KPA1500 <-> NereusSDR (or Thetis on another computer)
#  Design and on-air testing by KW4EX. No warranty. Use at your own risk.
#
#  How to run:  open Terminal, type   bash    (with a space after it),
#  drag this file into the Terminal window, press Enter.
# ======================================================================
set -u
OS="$(uname -s)"
case "$OS" in Darwin) OSNAME="Mac";; Linux) OSNAME="Linux";; *) echo "This installer is for Mac and Linux only."; exit 1;; esac
VERSION="2.49"
HOME_DIR="${KPA_HOME:-$HOME}"
TEST="${KPA_TEST:-}"
SELF="$0"

say()  { printf '%s\n' "$*"; }
head_() { printf '\n=== %s ===\n' "$*"; }
ask_text() {   # ask_text "question" "default"
  local a
  if [ -n "$2" ]; then printf '%s [%s]: ' "$1" "$2"; else printf '%s: ' "$1"; fi
  read -r a || a=""
  [ -z "$a" ] && a="$2"
  ANS="$a"
}
ask_yn() {   # ask_yn "question" y|n
  local d="$2" a
  while :; do
    if [ "$d" = y ]; then printf '%s (Y/n): ' "$1"; else printf '%s (y/N): ' "$1"; fi
    read -r a || a=""
    a="$(printf '%s' "$a" | tr 'A-Z' 'a-z')"
    [ -z "$a" ] && a="$d"
    case "$a" in y|yes) return 0;; n|no) return 1;; esac
    say "Please type y or n."
  done
}
is_ipv4() { printf '%s' "$1" | grep -Eq '^([0-9]{1,3}\.){3}[0-9]{1,3}$' && \
  [ "$(printf '%s' "$1" | awk -F. '{m=0; for(i=1;i<=4;i++) if($i>m) m=$i; print m}')" -le 255 ]; }

say "KPA1500 SDR Bridge $VERSION - installer for $OSNAME (experimental)"
say "No warranty. Use at your own risk."
say "Thetis windows (containers) are Windows-only and are not part of this installer."

# ---- 1. Python
head_ "Step 1 of 7: Python"
PYS=""
for c in python3 python; do
  if command -v "$c" >/dev/null 2>&1 && "$c" -c 'import sys; sys.exit(0 if sys.version_info >= (3, 8) else 1)' 2>/dev/null; then PYS="$c"; break; fi
done
if [ -z "$PYS" ]; then
  say "Python 3.8 or newer was not found."
  if [ "$OSNAME" = "Mac" ]; then
    say "  Install it, then run this installer again:"
    say "   - Easiest: in Terminal type   xcode-select --install   (installs Apple's command line tools, which include Python 3)"
    say "   - Or download Python from https://www.python.org/downloads/macos/"
  else
    say "  Install it, then run this installer again, for example:"
    say "   Debian / Ubuntu / Raspberry Pi OS:  sudo apt install python3 python3-venv"
    say "   Fedora:                             sudo dnf install python3"
  fi
  exit 1
fi
say "Found: $($PYS --version 2>&1) ($PYS)"

# ---- 2. folder
head_ "Step 2 of 7: install folder"
DEF_DIR="$HOME_DIR/RadioScripts/KPA1500_SDR_Bridge"
say "The bridge gets its own folder. The suggested place is RadioScripts in your home folder."
ask_text "Install folder" "$DEF_DIR"; DEST="$ANS"
case "$DEST" in "~"/*) DEST="$HOME_DIR/${DEST#\~/}";; esac
mkdir -p "$DEST" || { say "Could not create $DEST"; exit 1; }
DEST="$(cd "$DEST" && pwd)"
KEEP=0
if [ -f "$DEST/kpa1500_sdr_bridge.py" ] && [ -f "$DEST/kpa1500_start.conf" ]; then
  say "An earlier install was found here."
  if ask_yn "Keep your current start options (skips the questions about the amplifier, panel and LP-100A)?" y; then KEEP=1; fi
fi

# ---- unpack payload
WORK="$(mktemp -d "${TMPDIR:-/tmp}/kpa_install.XXXXXX")" || exit 1
trap 'rm -rf "$WORK"' EXIT
PL=$(awk '/^#PAYLOAD-BEGIN$/{print NR+1; exit}' "$SELF")
if [ -z "$PL" ]; then say "This installer file looks damaged (no payload). Please download it again."; exit 1; fi
tail -n +"$PL" "$SELF" | "$PYS" -c '
import sys, base64, io, tarfile
data = base64.b64decode("".join(sys.stdin.read().split()))
t = tarfile.open(fileobj=io.BytesIO(data))
try:
    t.extractall(sys.argv[1], filter="data")
except TypeError:
    t.extractall(sys.argv[1])
' "$WORK" || { say "Could not unpack the installer. Please download it again."; exit 1; }

STAMP="$(date +%Y%m%d_%H%M%S)"
if [ -f "$DEST/kpa1500_sdr_bridge.py" ]; then
  cp "$DEST/kpa1500_sdr_bridge.py" "$DEST/kpa1500_sdr_bridge.py.$STAMP.bak"
  say "The old program was saved as kpa1500_sdr_bridge.py.$STAMP.bak"
fi
[ -f "$DEST/kpa1500_start.conf" ] && cp "$DEST/kpa1500_start.conf" "$DEST/kpa1500_start.conf.$STAMP.bak"
cp "$WORK/kpa1500_sdr_bridge.py" "$WORK/KPA1500_Bridge_Help.html" "$WORK/README_Mac_Linux.txt" "$WORK/uninstall_kpa1500_sdr_bridge.sh" "$DEST/" || { say "Could not copy files into $DEST"; exit 1; }
chmod +x "$DEST/uninstall_kpa1500_sdr_bridge.sh"
say "Files copied to $DEST"

# ---- private Python with pyserial (so nothing is installed system-wide)
PYBIN="$PYS"
if [ -z "${KPA_TEST_NOPIP:-}" ]; then
  say "Setting up the bridge's own Python (for the LP-100A meter and the FlexControl knob) ..."
  if [ -x "$DEST/.venv/bin/python" ] || "$PYS" -m venv "$DEST/.venv" >/dev/null 2>&1; then
    if "$DEST/.venv/bin/python" -m pip install --quiet pyserial >/dev/null 2>&1; then
      PYBIN="$DEST/.venv/bin/python"; say "pyserial installed (inside $DEST/.venv)."
    else
      say "Could not download pyserial (no internet?). The bridge works without it; the LP-100A and knob need it."
      PYBIN="$DEST/.venv/bin/python"
    fi
  else
    say "Could not create the private Python (the venv part is missing)."
    [ "$OSNAME" = "Linux" ] && say "  On Debian / Ubuntu / Raspberry Pi OS run:  sudo apt install python3-venv   and run this installer again."
    say "  The bridge still works without it; the LP-100A meter and the knob need pyserial."
  fi
fi

# ---- start options
AMPFLAG=""; RADIOFLAG="--radio nereus"; TCIFLAG=""; LPFLAG=""; BINDFLAG=""; TOKFLAG=""
if [ "$KEEP" = 1 ]; then
  . "$DEST/kpa1500_start.conf" 2>/dev/null
  AMPFLAG="${CFG_AMP:-}"; LPFLAG="${CFG_LP:-}"; BINDFLAG="${CFG_BIND:-}"; TOKFLAG="${CFG_TOKEN:-}"
  RADIOFLAG="${CFG_RADIO:-$RADIOFLAG}"; TCIFLAG="${CFG_TCI:-}"
else
  # ---- 3. amplifier
  head_ "Step 3 of 7: finding the amplifier"
  say "The KPA1500 must be on and on the same network. Its network address looks like 192.168.1.50."
  say "  1  Search the network for it (recommended)"
  say "  2  I will type its address"
  say "  3  Skip (the bridge uses the address last chosen in its panel, else 192.168.0.175)"
  ask_text "Your choice" "1"; C="$ANS"
  AMPIP=""
  if [ "$C" = "1" ]; then
    say "Searching (about 10 seconds) ..."
    RAW="$(cd "$DEST" && "$PYBIN" kpa1500_sdr_bridge.py --discover 2>&1 | grep -E '^ +Found: +[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+')"
    OUT="$(printf '%s\n' "$RAW" | sed -E 's/^ +Found: +//; s/ +MAC .*$//' | awk 'NF{print NR "  " $0}')"
    if [ -n "$RAW" ]; then
      say "Found:"; say "$OUT"
      N="$(printf '%s\n' "$OUT" | wc -l | tr -d ' ')"
      if [ "$N" = "1" ]; then K=1; else ask_text "Number of the amplifier to use" "1"; K="$ANS"; fi
      AMPIP="$(printf '%s\n' "$OUT" | awk -v k="$K" '$1==k{print $2}')"
    else
      say "No amplifier was found. Check that it is on and on this network. You can type its address instead."
      C="2"
    fi
  fi
  if [ "$C" = "2" ]; then
    while :; do
      ask_text "Amplifier address (for example 192.168.1.50), or just Enter to skip" ""; A="$ANS"
      [ -z "$A" ] && break
      if is_ipv4 "$A"; then AMPIP="$A"; break; fi
      say "That is not an address like 192.168.1.50."
    done
  fi
  [ -n "$AMPIP" ] && { AMPFLAG="--amp-ip $AMPIP"; say "Amplifier: $AMPIP"; }

  # ---- 4. radio program
  head_ "Step 4 of 7: your radio program"
  say "  1  NereusSDR on this computer (recommended on a Mac)"
  say "  2  Thetis, Thetis HL2 or SDR-VST3 on another computer (a Windows PC, or Windows running in Parallels)"
  say "  3  Either one (the bridge finds out which is running)"
  ask_text "Your choice" "1"; R="$ANS"
  case "$R" in
    2) RADIOFLAG="--radio thetis"
       while :; do
         ask_text "Address of the computer that runs Thetis (for example 192.168.1.20)" ""; T="$ANS"
         is_ipv4 "$T" && break
         say "That is not an address like 192.168.1.20."
       done
       TCIFLAG="--tci-host $T"
       say "On that computer open Thetis > Setup > Serial/Network/Midi CAT > Network > TCI Server."
       say "Set it to listen on its network address (not 127.0.0.1), port 50001, and tick TCI Server Running."
       say "Allow port 50001 in that computer's firewall."
       ;;
    3) RADIOFLAG="--radio auto";;
    *) RADIOFLAG="--radio nereus";;
  esac
  # ---- 5. LP-100A
  head_ "Step 5 of 7: LP-100A power meter (optional)"
  PORTS=""
  for p in /dev/cu.usb* /dev/cu.SLAB* /dev/ttyUSB* /dev/ttyACM*; do [ -e "$p" ] && PORTS="$PORTS $p"; done
  if [ -z "$PORTS" ]; then
    say "No USB serial port was found. If you have an LP-100A, plug it in (USB) and run this installer again."
    say "You can also set it later in the panel (Settings, LP-100A port)."
  else
    i=1; for p in $PORTS; do say "  $i  $p"; i=$((i+1)); done
    say "  0  I have no LP-100A / skip"
    ask_text "Number of the LP-100A port" "0"; N="$ANS"
    if [ "$N" != "0" ] && [ -n "$N" ]; then
      i=1; for p in $PORTS; do [ "$i" = "$N" ] && LPFLAG="--lp100-port $p"; i=$((i+1)); done
    fi
  fi
  # ---- 6. panel
  head_ "Step 6 of 7: the browser panel and other devices"
  say "The panel is at http://127.0.0.1:8080 on this computer."
  if ask_yn "Also allow other computers, tablets and phones on your network to open it?" n; then
    BINDFLAG="--web-bind 0.0.0.0"
    while :; do
      ask_text "A password for the panel (4 to 32 letters or digits)" ""; P="$ANS"
      if printf '%s' "$P" | grep -Eq '^[A-Za-z0-9]{4,32}$'; then TOKFLAG="--web-token $P"; break; fi
      say "Please use 4 to 32 letters or digits (a password is needed when others can reach the panel)."
    done
    if [ "$OSNAME" = "Mac" ]; then say "The Mac may ask whether Python may accept incoming connections: click Allow."
    else say "If the Linux firewall is on, allow the port, for example:  sudo ufw allow 8080/tcp"; fi
  fi
fi

# ---- 7. scripts, shortcuts, test
head_ "Step 7 of 7: start files, shortcuts and test"
BRIDGE_FLAGS="$AMPFLAG $RADIOFLAG $TCIFLAG $LPFLAG $BINDFLAG $TOKFLAG"
BRIDGE_FLAGS="$(printf '%s' "$BRIDGE_FLAGS" | tr -s ' ' | sed 's/^ //; s/ $//')"
cat > "$DEST/kpa1500_start.conf" <<CONF
# Start options for the KPA1500 SDR bridge. Edit this file, then run start_kpa_sdr_bridge.sh again.
# One option per line is fine, but BRIDGE_FLAGS is what the bridge receives. Common options:
#   --amp-ip 192.168.1.50     amplifier address        --radio nereus|thetis|auto
#   --tci-host 192.168.1.20   radio program on another computer
#   --lp100-port /dev/cu.usbserial-XXXX   LP-100A      --web-bind 0.0.0.0 --web-token PASSWORD   other devices
#   --dry-run  (read only, nothing is sent to the amp)  --verbose  (more messages)
PY="$PYBIN"
BRIDGE_FLAGS="$BRIDGE_FLAGS"
# the pieces the installer remembers (used when you upgrade and keep your options)
CFG_AMP="$AMPFLAG"
CFG_RADIO="$RADIOFLAG"
CFG_TCI="$TCIFLAG"
CFG_LP="$LPFLAG"
CFG_BIND="$BINDFLAG"
CFG_TOKEN="$TOKFLAG"
CONF
cat > "$DEST/start_kpa_sdr_bridge.sh" <<'RUN'
#!/bin/bash
# Starts the KPA1500 SDR bridge. A bridge that is already running is closed first.
# Edit kpa1500_start.conf (next to this file) to change the options.
cd "$(dirname "$0")" || exit 1
. ./kpa1500_start.conf
APPLET="--applet"
[ -n "${KPA_NO_APPLET:-}" ] && APPLET=""
echo "Starting the KPA1500 SDR bridge. Leave this window open. To stop: press Q here, or run stop_bridge.sh."
exec "$PY" kpa1500_sdr_bridge.py --replace $APPLET $BRIDGE_FLAGS "$@"
RUN
cat > "$DEST/stop_bridge.sh" <<'RUN'
#!/bin/bash
# Closes the running bridge.
cd "$(dirname "$0")" || exit 1
. ./kpa1500_start.conf
"$PY" kpa1500_sdr_bridge.py --stop-running
RUN
cat > "$DEST/open_applet.sh" <<'RUN'
#!/bin/bash
# Opens the Applet window of the running bridge (the bridge must be running).
if ! curl -s -X POST -H "Content-Type: application/json" -H "X-KPA: 1" -d '{"action":"applet_window"}' http://127.0.0.1:8080/api/cmd >/dev/null 2>&1; then
  echo "The bridge does not seem to be running. Start it with start_kpa_sdr_bridge.sh"
fi
RUN
chmod +x "$DEST/start_kpa_sdr_bridge.sh" "$DEST/stop_bridge.sh" "$DEST/open_applet.sh"
if [ "$OSNAME" = "Mac" ]; then
  for pair in "Start KPA1500 SDR Bridge:start_kpa_sdr_bridge.sh" "Stop KPA1500 SDR Bridge:stop_bridge.sh" \
              "Open KPA1500 Applet:open_applet.sh" "Uninstall KPA1500 SDR Bridge:uninstall_kpa1500_sdr_bridge.sh"; do
    nm="${pair%%:*}"; sc="${pair#*:}"
    printf '#!/bin/bash\nexec "$(dirname "$0")/%s"\n' "$sc" > "$DEST/$nm.command"
    chmod +x "$DEST/$nm.command"
  done
  say "On a Mac you can double-click the .command files in the install folder."
fi
say "Start files written: start_kpa_sdr_bridge.sh, stop_bridge.sh, open_applet.sh, uninstall_kpa1500_sdr_bridge.sh"

if ask_yn "Put a start shortcut on the Desktop?" y; then
  mkdir -p "$HOME_DIR/Desktop"
  if [ "$OSNAME" = "Mac" ]; then
    ln -sf "$DEST/Start KPA1500 SDR Bridge.command" "$HOME_DIR/Desktop/KPA1500 SDR Bridge.command"
  else
    cat > "$HOME_DIR/Desktop/KPA1500 SDR Bridge.desktop" <<DSK
[Desktop Entry]
Type=Application
Name=KPA1500 SDR Bridge
Exec=$DEST/start_kpa_sdr_bridge.sh
Path=$DEST
Terminal=true
DSK
    chmod +x "$HOME_DIR/Desktop/KPA1500 SDR Bridge.desktop"
    mkdir -p "$HOME_DIR/.local/share/applications"
    cp "$HOME_DIR/Desktop/KPA1500 SDR Bridge.desktop" "$HOME_DIR/.local/share/applications/kpa1500-sdr-bridge.desktop"
  fi
  say "Desktop shortcut made."
fi

if ask_yn "Start the bridge automatically when you sign in?" n; then
  if [ "$OSNAME" = "Mac" ]; then
    PLD="$HOME_DIR/Library/LaunchAgents"; mkdir -p "$PLD"
    cat > "$PLD/com.kw4ex.kpa1500sdrbridge.plist" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
 <key>Label</key><string>com.kw4ex.kpa1500sdrbridge</string>
 <key>ProgramArguments</key><array><string>$DEST/start_kpa_sdr_bridge.sh</string></array>
 <key>WorkingDirectory</key><string>$DEST</string>
 <key>RunAtLoad</key><true/>
 <key>StandardOutPath</key><string>$DEST/launchd.log</string>
 <key>StandardErrorPath</key><string>$DEST/launchd.log</string>
</dict></plist>
PLIST
    [ -z "$TEST" ] && { launchctl bootstrap "gui/$(id -u)" "$PLD/com.kw4ex.kpa1500sdrbridge.plist" 2>/dev/null || launchctl load "$PLD/com.kw4ex.kpa1500sdrbridge.plist" 2>/dev/null; }
    say "Login item added. (To undo: run the uninstaller, or delete $PLD/com.kw4ex.kpa1500sdrbridge.plist)"
    say "Note: a sleeping Mac stops the bridge, and a closed lid on battery power puts it to sleep."
  else
    if command -v systemctl >/dev/null 2>&1; then
      UD="$HOME_DIR/.config/systemd/user"; mkdir -p "$UD"
      cat > "$UD/kpa1500-sdr-bridge.service" <<UNIT
[Unit]
Description=KPA1500 SDR Bridge
After=network-online.target

[Service]
Type=simple
WorkingDirectory=$DEST
Environment=KPA_NO_APPLET=1
ExecStart=$DEST/start_kpa_sdr_bridge.sh
Restart=on-failure
RestartSec=5

[Install]
WantedBy=default.target
UNIT
      if [ -z "$TEST" ]; then
        systemctl --user daemon-reload >/dev/null 2>&1
        systemctl --user enable --now kpa1500-sdr-bridge.service >/dev/null 2>&1 && say "Service installed and started (it restarts if it stops)." \
          || say "The service file was written, but it could not be started. Try:  systemctl --user enable --now kpa1500-sdr-bridge.service"
      else
        say "Service file written."
      fi
      say "To start it even when nobody is signed in:  sudo loginctl enable-linger $(id -un)"
    else
      say "This Linux has no systemd, so no automatic start was set up. Start the bridge with start_kpa_sdr_bridge.sh."
    fi
  fi
fi

if [ -z "${KPA_TEST_NOSELFTEST:-}" ] && ask_yn "Run a quick self-test of the program now (about two minutes, uses simulated hardware)?" n; then
  say "Testing ..."
  (cd "$DEST" && "$PYBIN" kpa1500_sdr_bridge.py --selftest > install_selftest.txt 2>&1)
  LAST="$(grep -E 'ALL TESTS PASSED|SOME TESTS FAILED' "$DEST/install_selftest.txt" | tail -1)"
  if printf '%s' "$LAST" | grep -q 'ALL TESTS PASSED'; then say "$LAST"
  else
    say "The self-test did not fully pass. The bridge may still work; details are in $DEST/install_selftest.txt"
    say "Please send that file to whoever gave you this installer."
  fi
fi

head_ "Done"
say "Installed in: $DEST"
if [ "$KEEP" = 0 ] && [ "${RADIOFLAG}" != "--radio thetis" ]; then
  say ""
  say "In NereusSDR set these once (File > Settings > CAT & Network):"
  say "  TCI Server page:  tick Enable TCI Server, Listen on 127.0.0.1, Port 50001."
  say "  TCP/IP CAT page:  tick Enable TCP CAT. CAT 1: Listen on 127.0.0.1, Port 13013."
  say "                    Set VFO A = Slice A (it may show as Slice ID 0). Leave VFO B empty."
  say "  Without the VFO A binding the knob and the TUNE button do nothing."
  say "  Only one radio program can use port 50001 at a time."
  say "  TUNE needs this NereusSDR window to hold transmit control (TXcontrol)."
fi
say ""
say "To start:  $DEST/start_kpa_sdr_bridge.sh   (Mac: double-click 'Start KPA1500 SDR Bridge.command')"
say "Panel:     http://127.0.0.1:8080        Help:  $DEST/KPA1500_Bridge_Help.html"
say "To remove everything later:  bash $DEST/uninstall_kpa1500_sdr_bridge.sh"
if ask_yn "Start the bridge now?" y; then
  if [ -z "$TEST" ]; then
    if [ "$OSNAME" = "Mac" ]; then open "$DEST/Start KPA1500 SDR Bridge.command" 2>/dev/null || "$DEST/start_kpa_sdr_bridge.sh"
    else "$DEST/start_kpa_sdr_bridge.sh"; fi
  fi
fi
exit 0
